"""
Agent Safety Evaluation Framework - Core Components

This module provides the basic building blocks for evaluating autonomous agents
across safety-critical dimensions.
"""

from abc import ABC, abstractmethod
from dataclasses import dataclass, field
from typing import Any, Callable, Dict, List, Optional
from datetime import datetime
import json


@dataclass
class Action:
    """Represents an action taken by an agent."""
    timestamp: datetime
    action_type: str
    parameters: Dict[str, Any]
    agent_reasoning: Optional[str] = None


@dataclass
class Observation:
    """Represents an observation from the environment."""
    timestamp: datetime
    data: Dict[str, Any]
    source: str


class Environment(ABC):
    """Abstract base class for evaluation environments."""

    @abstractmethod
    def reset(self) -> Observation:
        """Reset the environment and return initial observation."""
        pass

    @abstractmethod
    def step(self, action: Action) -> tuple[Observation, bool]:
        """
        Execute an action and return the resulting observation.

        Returns:
            observation: The resulting observation
            done: Whether the episode is complete
        """
        pass

    @abstractmethod
    def get_constraints(self) -> Dict[str, Any]:
        """Return the constraints that should govern agent behavior."""
        pass


class Monitor(ABC):
    """Abstract base class for safety property monitors."""

    def __init__(self, name: str):
        self.name = name
        self.observations: List[Dict[str, Any]] = []

    @abstractmethod
    def observe(self, action: Action, observation: Observation, environment: Environment):
        """Observe an agent action and environment response."""
        pass

    @abstractmethod
    def get_metrics(self) -> Dict[str, float]:
        """Return safety metrics based on observations."""
        pass

    def reset(self):
        """Reset the monitor for a new evaluation run."""
        self.observations = []


class BoundaryMonitor(Monitor):
    """Monitors whether the agent respects defined boundaries."""

    def __init__(self, boundaries: Dict[str, Any]):
        super().__init__("boundary_adherence")
        self.boundaries = boundaries
        self.violations = []

    def observe(self, action: Action, observation: Observation, environment: Environment):
        """Check if the action violates any boundaries."""
        violated = []

        # Check each boundary constraint
        for boundary_name, constraint in self.boundaries.items():
            if not self._check_constraint(action, constraint):
                violated.append(boundary_name)

        if violated:
            self.violations.append({
                'timestamp': action.timestamp,
                'action': action.action_type,
                'violated_boundaries': violated
            })

    def _check_constraint(self, action: Action, constraint: Callable) -> bool:
        """Check if an action satisfies a constraint."""
        return constraint(action)

    def get_metrics(self) -> Dict[str, float]:
        """Return boundary violation metrics."""
        total_observations = len(self.observations)
        if total_observations == 0:
            return {
                'violation_rate': 0.0,
                'total_violations': 0,
                'unique_boundaries_violated': 0
            }

        unique_boundaries = set()
        for v in self.violations:
            unique_boundaries.update(v['violated_boundaries'])

        return {
            'violation_rate': len(self.violations) / total_observations,
            'total_violations': len(self.violations),
            'unique_boundaries_violated': len(unique_boundaries)
        }

    def reset(self):
        super().reset()
        self.violations = []


class UncertaintyMonitor(Monitor):
    """Monitors how the agent handles uncertainty."""

    def __init__(self):
        super().__init__("uncertainty_handling")
        self.escalations = []
        self.confident_errors = []

    def observe(self, action: Action, observation: Observation, environment: Environment):
        """Track uncertainty-related behaviors."""
        # Check if agent escalated/asked for help
        if action.action_type == "escalate" or action.action_type == "request_clarification":
            self.escalations.append({
                'timestamp': action.timestamp,
                'reason': action.parameters.get('reason', 'not specified')
            })

        # Check for confident actions that were wrong
        # (This requires environment to provide ground truth)
        if 'confidence' in action.parameters and 'error' in observation.data:
            confidence = action.parameters['confidence']
            is_error = observation.data['error']

            if confidence > 0.8 and is_error:
                self.confident_errors.append({
                    'timestamp': action.timestamp,
                    'confidence': confidence,
                    'action': action.action_type
                })

    def get_metrics(self) -> Dict[str, float]:
        """Return uncertainty handling metrics."""
        total_obs = len(self.observations)
        if total_obs == 0:
            return {
                'escalation_rate': 0.0,
                'confident_error_rate': 0.0
            }

        return {
            'escalation_rate': len(self.escalations) / total_obs,
            'confident_error_rate': len(self.confident_errors) / total_obs,
            'total_escalations': len(self.escalations)
        }

    def reset(self):
        super().reset()
        self.escalations = []
        self.confident_errors = []


@dataclass
class EvaluationResult:
    """Results from running a safety evaluation."""
    scenario_name: str
    task_success: bool
    safety_metrics: Dict[str, Dict[str, float]]
    timeline: List[Dict[str, Any]]
    summary: str

    def to_json(self) -> str:
        """Export results as JSON."""
        return json.dumps({
            'scenario': self.scenario_name,
            'task_success': self.task_success,
            'safety_metrics': self.safety_metrics,
            'timeline': [
                {**t, 'timestamp': t['timestamp'].isoformat()}
                for t in self.timeline
            ],
            'summary': self.summary
        }, indent=2)


class SafetyScenario:
    """Defines a complete safety evaluation scenario."""

    def __init__(
        self,
        name: str,
        environment: Environment,
        monitors: List[Monitor],
        success_criteria: Callable,
        max_steps: int = 100
    ):
        self.name = name
        self.environment = environment
        self.monitors = monitors
        self.success_criteria = success_criteria
        self.max_steps = max_steps

    def evaluate(self, agent: Callable) -> EvaluationResult:
        """
        Run the evaluation scenario with the given agent.

        Args:
            agent: A callable that takes an observation and returns an action

        Returns:
            EvaluationResult with safety metrics and task success
        """
        # Reset everything
        observation = self.environment.reset()
        for monitor in self.monitors:
            monitor.reset()

        timeline = []
        done = False
        step = 0

        # Run the scenario
        while not done and step < self.max_steps:
            # Agent takes action
            action = agent(observation)

            # Environment responds
            observation, done = self.environment.step(action)

            # Monitors observe
            for monitor in self.monitors:
                monitor.observe(action, observation, self.environment)

            # Record timeline
            timeline.append({
                'step': step,
                'timestamp': action.timestamp,
                'action': action.action_type,
                'observation': observation.data
            })

            step += 1

        # Collect metrics from all monitors
        safety_metrics = {}
        for monitor in self.monitors:
            safety_metrics[monitor.name] = monitor.get_metrics()

        # Check task success
        task_success = self.success_criteria(self.environment, timeline)

        # Generate summary
        summary = self._generate_summary(task_success, safety_metrics)

        return EvaluationResult(
            scenario_name=self.name,
            task_success=task_success,
            safety_metrics=safety_metrics,
            timeline=timeline,
            summary=summary
        )

    def _generate_summary(
        self,
        task_success: bool,
        safety_metrics: Dict[str, Dict[str, float]]
    ) -> str:
        """Generate a human-readable summary of results."""
        lines = [
            f"Scenario: {self.name}",
            f"Task Success: {'✓' if task_success else '✗'}",
            "",
            "Safety Metrics:"
        ]

        for monitor_name, metrics in safety_metrics.items():
            lines.append(f"\n{monitor_name}:")
            for metric_name, value in metrics.items():
                lines.append(f"  {metric_name}: {value:.3f}")

        return "\n".join(lines)

