        return json.dumps({
            'scenario': self.scenario_name,
            'task_success': self.task_success,
            'safety_metrics': self.safety_metrics,
            'timeline': [
                {**t, 'timestamp': t['timestamp'].isoformat()}
                for t in self.timeline
            ],
            'summary': self.summary
        }, indent=2)


class SafetyScenario:
    """Defines a complete safety evaluation scenario."""

    def __init__(
        self,
        name: str,
        environment: Environment,
        monitors: List[Monitor],
        success_criteria: Callable,
        max_steps: int = 100
    ):
        self.name = name
        self.environment = environment
        self.monitors = monitors
        self.success_criteria = success_criteria
        self.max_steps = max_steps

    def evaluate(self, agent: Callable) -> EvaluationResult:
        """
        Run the evaluation scenario with the given agent.

        Args:
            agent: A callable that takes an observation and returns an action

        Returns:
            EvaluationResult with safety metrics and task success
        """
        # Reset everything
        observation = self.environment.reset()
        for monitor in self.monitors:
            monitor.reset()

        timeline = []
        done = False
        step = 0

        # Run the scenario
        while not done and step < self.max_steps:
            # Agent takes action
            action = agent(observation)

            # Environment responds
            observation, done = self.environment.step(action)

            # Monitors observe
            for monitor in self.monitors:
                monitor.observe(action, observation, self.environment)

            # Record timeline
            timeline.append({
                'step': step,
                'timestamp': action.timestamp,
                'action': action.action_type,
                'observation': observation.data
            })

            step += 1

        # Collect metrics from all monitors
        safety_metrics = {}
        for monitor in self.monitors:
            safety_metrics[monitor.name] = monitor.get_metrics()

        # Check task success
        task_success = self.success_criteria(self.environment, timeline)

        # Generate summary
        summary = self._generate_summary(task_success, safety_metrics)

        return EvaluationResult(
            scenario_name=self.name,
            task_success=task_success,
            safety_metrics=safety_metrics,
            timeline=timeline,
            summary=summary
        )

    def _generate_summary(
        self,
        task_success: bool,
        safety_metrics: Dict[str, Dict[str, float]]
    ) -> str:
        """Generate a human-readable summary of results."""
        lines = [
            f"Scenario: {self.name}",
            f"Task Success: {'✓' if task_success else '✗'}",
            "",
            "Safety Metrics:"
        ]

        for monitor_name, metrics in safety_metrics.items():
            lines.append(f"\n{monitor_name}:")
            for metric_name, value in metrics.items():
                lines.append(f"  {metric_name}: {value:.3f}")

        return "\n".join(lines)

